function DashboardScreen({ username, onNav }) {
  const { t, lang } = useLang();
  const tips = TIPS_DATA[lang] || TIPS_DATA.English;
  const [tip] = useState(() => tips[Math.floor(Math.random() * tips.length)]);
  const FEATURES = [
    { id: "symptom", icon: "🔬", label: t.symptomChecker, color: C.accent, desc: t.symptomDesc },
    { id: "chat", icon: "💬", label: t.aiHealthChat, color: C.blue, desc: t.aiChatDesc },
    { id: "emergency", icon: "🚨", label: t.emergency, color: C.danger, desc: t.emergencyDesc },
    { id: "hospitals", icon: "🏥", label: t.nearbyHospitals, color: C.orange, desc: t.hospitalDesc },
    { id: "reminder", icon: "💊", label: t.medReminders, color: C.purple, desc: t.reminderDesc },
    { id: "library", icon: "📚", label: t.healthLibrary, color: C.teal, desc: t.libraryDesc },
  ];
  return (
    <div style={{ overflowY: "auto", padding: "18px 16px 8px", height: "100%" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
        <div>
          <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, letterSpacing: 0.4, textTransform: "uppercase" }}>{t.welcomeBack}</div>
          <div style={{ fontSize: 20, fontWeight: 800, color: C.text, letterSpacing: -0.3 }}>{t.hi}, {username} 👋</div>
        </div>
        <div style={{ width: 40, height: 40, borderRadius: 12, background: `linear-gradient(135deg,${C.accent},#009E5A)`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, boxShadow: `0 4px 16px ${C.accentGlow}` }}>🩺</div>
      </div>
      <Card style={{ marginBottom: 16, background: `linear-gradient(135deg,${C.accent}12,${C.blue}08)`, border: `1px solid ${C.accent}33` }}>
        <div style={{ fontSize: 10, fontWeight: 700, color: C.accent, letterSpacing: 0.6, textTransform: "uppercase", marginBottom: 5 }}>💡 {t.dailyTip}</div>
        <div style={{ fontSize: 13, color: C.text, lineHeight: 1.6 }}>{tip}</div>
      </Card>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 16 }}>
        {[{ icon: "🔥", val: "1,240", label: t.cal }, { icon: "💧", val: "6/8", label: t.water }, { icon: "👣", val: "4,230", label: t.steps }].map((s, i) => (
          <Card key={i} style={{ textAlign: "center", padding: "12px 8px" }}>
            <div style={{ fontSize: 20, marginBottom: 3 }}>{s.icon}</div>
            <div style={{ fontSize: 15, fontWeight: 800, color: C.text }}>{s.val}</div>
            <div style={{ fontSize: 10, color: C.muted }}>{s.label}</div>
          </Card>
        ))}
      </div>
      <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 10 }}>{t.services}</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        {FEATURES.map((f, i) => (
          <Card key={f.id} onClick={() => onNav(f.id)} style={{ cursor: "pointer", padding: "14px", animation: `fadeUp 0.4s ${i * 0.07}s ease both` }}
            onMouseEnter={e => e.currentTarget.style.borderColor = f.color + "66"} onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: `${f.color}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, marginBottom: 8, border: `1px solid ${f.color}30` }}>{f.icon}</div>
            <div style={{ fontSize: 12, fontWeight: 700, color: C.text, marginBottom: 2 }}>{f.label}</div>
            <div style={{ fontSize: 10, color: C.muted, lineHeight: 1.4 }}>{f.desc}</div>
          </Card>
        ))}
      </div>
      <div style={{ height: 12 }} />
    </div>
  );
}

