const DEFAULT_HOSPITALS = [
  { name: "District Government Hospital", type: "Government", area: "City Centre", address: "District Hospital Road, City Centre", phone: "104", emergency: true, speciality: "Multi-Specialty", beds: 300, rating: 4.1, dist_km: 2.0 },
  { name: "Apollo Clinic", type: "Private", area: "Main Road", address: "Apollo Clinic, Main Road", phone: "1860-500-1066", emergency: true, speciality: "General Medicine", beds: 50, rating: 4.3, dist_km: 3.5 },
  { name: "Primary Health Centre", type: "Government", area: "Near Bus Stand", address: "PHC Road, Near Bus Stand", phone: "104", emergency: false, speciality: "Primary Care", beds: 30, rating: 3.9, dist_km: 1.2 },
];

function HospitalsScreen() {
  const { t } = useLang();
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [selectedCity, setSelectedCity] = useState("Mumbai, Maharashtra");
  const [selectedRadius, setSelectedRadius] = useState("5 km");
  const [searched, setSearched] = useState(false);
  const [filterType, setFilterType] = useState("All");

  const CITY_COORDS = {
    "Mumbai, Maharashtra": [19.0760, 72.8777],
    "Delhi, Delhi": [28.7041, 77.1025],
    "Bengaluru, Karnataka": [12.9716, 77.5946],
    "Chennai, Tamil Nadu": [13.0827, 80.2707],
    "Hyderabad, Telangana": [17.3850, 78.4867],
    "Kolkata, West Bengal": [22.5726, 88.3639],
    "Pune, Maharashtra": [18.5204, 73.8567],
    "Kochi, Kerala": [9.9312, 76.2673]
  };

  const searchHospitals = () => {
    setLoading(true); setHospitals([]); setSearched(true); setSearch("");
    setTimeout(() => {
      const radiusKm = parseFloat(selectedRadius);
      // Get from built-in DB or fallback
      const cityKey = Object.keys(HOSPITAL_DB).find(k => k === selectedCity);
      const allForCity = cityKey ? HOSPITAL_DB[cityKey] : DEFAULT_HOSPITALS;
      // Filter by radius
      const inRange = allForCity.filter(h => h.dist_km <= radiusKm);
      setHospitals(inRange.sort((a, b) => a.dist_km - b.dist_km));
      setLoading(false);
    }, 600);
  };

  const types = ["All", "Government", "Private", "Trust", "Clinic"];
  const typeLabels = { All: t.filterAll, Government: t.filterGovt, Private: t.filterPrivate, Trust: t.filterTrust, Clinic: t.filterClinic };
  const typeColor = tp => ({ Government: C.blue, Private: C.orange, Trust: C.teal, Clinic: C.purple }[tp] || C.muted);

  const filtered = hospitals.filter(h => {
    const matchSearch = !search || h.name.toLowerCase().includes(search.toLowerCase()) || h.area.toLowerCase().includes(search.toLowerCase()) || h.speciality.toLowerCase().includes(search.toLowerCase());
    const matchType = filterType === "All" || h.type === filterType;
    return matchSearch && matchType;
  });

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", overflow: "hidden" }}>
      {/* Header */}
      <div style={{ padding: "12px 16px 10px", background: C.card, borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.text }}>🏥 {t.nearbyHospitals}</div>
        <div style={{ fontSize: 11, color: C.muted }}>{t.hospitalDirectory}</div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "12px 14px 8px" }}>

        {/* Search panel */}
        <Card style={{ marginBottom: 12, padding: "12px 14px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, color: C.accent, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 10 }}>{t.selectCityRadius}</div>

          {/* City dropdown */}
          <div style={{ position: "relative", marginBottom: 10 }}>
            <span style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", fontSize: 13, opacity: 0.5, pointerEvents: "none" }}>🏙️</span>
            <select value={selectedCity} onChange={e => setSelectedCity(e.target.value)}
              style={{ width: "100%", background: C.cardHover, border: `1.5px solid ${C.border}`, borderRadius: 10, padding: "10px 14px 10px 36px", fontSize: 13, color: C.text, appearance: "none", cursor: "pointer" }}>
              {INDIA_CITIES.map(c => <option key={c} value={c} style={{ background: C.card }}>{c}</option>)}
            </select>
          </div>

          {/* Radius */}
          <div style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 10, color: C.textSub, fontWeight: 600, marginBottom: 6 }}>SEARCH RADIUS</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {RADIUS_OPTIONS.map(r => (
                <button key={r} onClick={() => setSelectedRadius(r)}
                  style={{ padding: "5px 11px", borderRadius: 20, border: `1.5px solid ${selectedRadius === r ? C.accent : C.border}`, background: selectedRadius === r ? C.accentDim : C.card, color: selectedRadius === r ? C.accent : C.muted, fontSize: 11, cursor: "pointer", fontWeight: selectedRadius === r ? 700 : 400, transition: "all 0.2s" }}>
                  {r}
                </button>
              ))}
            </div>
          </div>

          <Btn onClick={searchHospitals} loading={loading}>
            {loading ? t.searching : `${t.findHospitalsIn} ${selectedCity.split(",")[0]}`}
          </Btn>
        </Card>

        {/* Loading skeletons */}
        {loading && [1, 2, 3].map(i => <Skeleton key={i} />)}

        {/* Quick city shortcuts */}
        {!loading && !searched && (
          <div style={{ animation: "fadeUp 0.5s ease" }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 10 }}>{t.quickSelectCity}</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 16 }}>
              {["Mumbai", "Delhi", "Bengaluru", "Chennai", "Hyderabad", "Kolkata", "Pune", "Kochi"].map(c => (
                <button key={c}
                  onClick={() => {
                    const city = INDIA_CITIES.find(x => x.startsWith(c)) || c;
                    setSelectedCity(city);
                    setSelectedRadius("10 km");
                    // Auto search
                    setLoading(true); setHospitals([]); setSearched(true); setSearch("");
                    setTimeout(() => {
                      const db = HOSPITAL_DB[city] || DEFAULT_HOSPITALS;
                      setHospitals(db.sort((a, b) => a.dist_km - b.dist_km));
                      setLoading(false);
                    }, 500);
                  }}
                  style={{ padding: "10px 12px", background: C.card, border: `1.5px solid ${C.border}`, borderRadius: 12, color: C.textSub, fontSize: 12, cursor: "pointer", fontWeight: 600, transition: "all 0.2s", textAlign: "left", display: "flex", alignItems: "center", gap: 7 }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = C.accent; e.currentTarget.style.color = C.accent; e.currentTarget.style.background = C.accentDim; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = C.border; e.currentTarget.style.color = C.textSub; e.currentTarget.style.background = C.card; }}>
                  <span style={{ fontSize: 16 }}>🏥</span> {c}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Results */}
        {!loading && searched && (
          <div>
            {/* Search + filter bar */}
            <div style={{ marginBottom: 10 }}>
              <div style={{ position: "relative", marginBottom: 8 }}>
                <span style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", fontSize: 13, opacity: 0.4, pointerEvents: "none" }}>🔍</span>
                <input value={search} onChange={e => setSearch(e.target.value)}
                  placeholder={`${t.searchInHospitals || "Search"} ${hospitals.length} ${(t.hospitalsFound || "Hospitals found").split(" ")[0]}...`}
                  style={{ width: "100%", background: C.card, border: `1.5px solid ${search ? C.accent : C.border}`, borderRadius: 10, padding: "10px 14px 10px 34px", fontSize: 13, color: C.text, transition: "all 0.2s" }}
                />
              </div>
              {/* Type filter pills */}
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {types.map(tp => (
                  <button key={tp} onClick={() => setFilterType(tp)}
                    style={{ padding: "4px 10px", borderRadius: 20, border: `1.5px solid ${filterType === tp ? typeColor(tp) : C.border}`, background: filterType === tp ? `${typeColor(tp)}18` : C.card, color: filterType === tp ? typeColor(tp) : C.muted, fontSize: 11, cursor: "pointer", fontWeight: filterType === tp ? 700 : 400, transition: "all 0.2s" }}>
                    {tp}
                  </button>
                ))}
              </div>
            </div>

            {/* Results header */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: C.muted }}>
                {filtered.length} {t.hospitalsFound || "Hospitals found"}
              </div>
              <Badge color={C.accent}>{selectedRadius} · {selectedCity.split(",")[0]}</Badge>
            </div>

            {/* No results */}
            {filtered.length === 0 && (
              <div style={{ textAlign: "center", padding: "30px 20px" }}>
                <div style={{ fontSize: 36, marginBottom: 10 }}>🔍</div>
                <div style={{ fontSize: 14, color: C.textSub, marginBottom: 6 }}>No {t.hospitalsFound || "Hospitals found"}</div>
                <div style={{ fontSize: 12, color: C.muted }}>{t.tryIncreasingRadius}</div>
                <div style={{ marginTop: 14 }}>
                  <Btn onClick={() => setSelectedRadius("20 km")} small>{t.try20km}</Btn>
                </div>
              </div>
            )}

            {/* Google Maps View */}
            <div style={{ height: 300, width: "100%", marginBottom: 16, borderRadius: 12, overflow: "hidden", position: "relative" }}>
              <iframe
                width="100%"
                height="100%"
                frameBorder="0"
                scrolling="no"
                marginHeight="0"
                marginWidth="0"
                src={`https://maps.google.com/maps?q=${encodeURIComponent('hospitals near ' + selectedCity.split(',')[0])}&t=&z=13&ie=UTF8&iwloc=&output=embed`}
              />
            </div>

            {/* Hospital cards */}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {filtered.map((h, i) => (
                <Card key={i} style={{ animation: `fadeUp 0.3s ${Math.min(i, 7) * 0.04}s ease both`, padding: "13px 14px" }}>
                  {/* Top row */}
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
                    <div style={{ flex: 1, marginRight: 8 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, color: C.text, lineHeight: 1.35 }}>{h.name}</div>
                      <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>📍 {h.area}</div>
                    </div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 3, alignItems: "flex-end", flexShrink: 0 }}>
                      <Badge color={typeColor(h.type)}>{h.type}</Badge>
                      {h.emergency && <Badge color={C.danger}>🚨 24/7</Badge>}
                    </div>
                  </div>

                  {/* Speciality tag */}
                  <div style={{ marginBottom: 7 }}>
                    <span style={{ fontSize: 11, background: `${C.blue}15`, border: `1px solid ${C.blue}30`, borderRadius: 6, padding: "2px 8px", color: C.blue, fontWeight: 600 }}>
                      {h.speciality}
                    </span>
                  </div>

                  {/* Address */}
                  <div style={{ fontSize: 11, color: C.muted, marginBottom: 8, lineHeight: 1.4 }}>
                    {h.address}
                  </div>

                  {/* Stats */}
                  <div style={{ display: "flex", gap: 14, marginBottom: 10 }}>
                    <span style={{ fontSize: 11, color: C.textSub }}>🛏️ {h.beds} {t.bedsLabel}</span>
                    <span style={{ fontSize: 11, color: C.warn }}>⭐ {h.rating.toFixed(1)}</span>
                    <span style={{ fontSize: 11, fontWeight: 800, color: C.accent }}>📍 {h.dist_km.toFixed(1)} km</span>
                  </div>

                  {/* Phone number — visible & tappable */}
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 9, padding: "7px 10px", background: `${C.accent}10`, border: `1px solid ${C.accent}30`, borderRadius: 8 }}>
                    <span style={{ fontSize: 13 }}>📞</span>
                    <a href={`tel:${h.phone.replace(/[^0-9+]/g, "")}`}
                      style={{ fontSize: 13, fontWeight: 800, color: C.accent, textDecoration: "none", flex: 1, letterSpacing: 0.3 }}>
                      {h.phone}
                    </a>
                    <button
                      onClick={() => { navigator.clipboard?.writeText(h.phone).catch(() => { }); alert(`"📋 Copied!\n\nCall": ${h.phone}\n\nDial this number to reach ${h.name}`); }}
                      style={{ background: `${C.accent}20`, border: `1px solid ${C.accent}44`, borderRadius: 6, padding: "3px 8px", fontSize: 10, color: C.accent, cursor: "pointer", fontWeight: 700, flexShrink: 0 }}>
                      {t.copyBtn}
                    </button>
                  </div>

                  {/* Action buttons */}
                  <div style={{ display: "flex", gap: 7 }}>
                    <a href={`tel:${h.phone.replace(/[^0-9+]/g, "")}`}
                      style={{ flex: 1, padding: "9px 6px", background: `linear-gradient(135deg,${C.accent},#009E5A)`, border: "none", borderRadius: 9, fontSize: 12, color: "#021A0E", fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", gap: 4, textDecoration: "none", boxShadow: `0 3px 12px ${C.accentGlow}` }}>
                      {t.callNow}
                    </a>
                    <a href={`https://www.google.com/maps/search/${encodeURIComponent(h.name + " " + h.address)}`}
                      target="_blank" rel="noreferrer"
                      style={{ flex: 1, padding: "9px 6px", background: `${C.blue}18`, border: `1px solid ${C.blue}44`, borderRadius: 9, fontSize: 12, color: C.blue, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 4, textDecoration: "none" }}>
                      {t.directionsMap}
                    </a>
                    <a href={`https://www.google.com/search?q=${encodeURIComponent(h.name + " " + selectedCity + " hospital")}`}
                      target="_blank" rel="noreferrer"
                      style={{ padding: "9px 10px", background: `${C.purple}18`, border: `1px solid ${C.purple}44`, borderRadius: 9, fontSize: 12, color: C.purple, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", textDecoration: "none" }}>
                      🌐
                    </a>
                  </div>
                </Card>
              ))}
            </div>

            {filtered.length > 0 && (
              <div style={{ marginTop: 12, padding: "8px 12px", background: C.card, borderRadius: 10, border: `1px solid ${C.border}`, fontSize: 10, color: C.muted, textAlign: "center" }}>
                {t.hospitalDataVerify}
              </div>
            )}
            <div style={{ height: 12 }} />
          </div>
        )}
      </div>
    </div>
  );
}

// ─── MEDICINE REMINDERS ───────────────────────────────────────────────────────
// ─── ALARM SOUND via Web Audio API ───────────────────────────────────────────
// ─── AUDIO ENGINE ─────────────────────────────────────────────────────────────
let _audioCtx = null;
let _masterGain = null;
let _alarmNodes = []; // track all running nodes so we can stop them

function getAudioCtx() {
  if (!_audioCtx || _audioCtx.state === "closed") {
    _audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    _masterGain = _audioCtx.createGain();
    _masterGain.gain.value = 0.85;
    _masterGain.connect(_audioCtx.destination);
  }
  if (_audioCtx.state === "suspended") _audioCtx.resume();
  return _audioCtx;
}

function stopAllAlarmSounds() {
  _alarmNodes.forEach(n => { try { n.stop(); } catch (e) { } });
  _alarmNodes = [];
}

// ── Note helper ───────────────────────────────────────────────────────────────
// type: "sine"|"square"|"triangle"|"sawtooth"
function scheduleNote(ctx, dest, freq, startT, dur, vol = 0.6, type = "sine", attack = 0.01, release = 0.06) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  osc.connect(gain);
  gain.connect(dest);
  gain.gain.setValueAtTime(0, startT);
  gain.gain.linearRampToValueAtTime(vol, startT + attack);
  gain.gain.setValueAtTime(vol, startT + dur - release);
  gain.gain.linearRampToValueAtTime(0, startT + dur);
  osc.start(startT);
  osc.stop(startT + dur + 0.05);
  _alarmNodes.push(osc);
}

// ── Musical ringtone: Joyful Medicine Bell ──────────────────────────────
// A cheerful, impossible-to-ignore Indian-style alarm melody
function playAlarmSound() {
  try {
    const ctx = getAudioCtx();
    const dest = _masterGain;
    const t = ctx.currentTime + 0.05;

    // Note frequencies
    const C5 = 523, D5 = 587, E5 = 659, F5 = 698, G5 = 784, A5 = 880, B5 = 988, C6 = 1047;
    const E4 = 330, G4 = 392, C4 = 262;

    // ── MELODY (bright sine, main tune) ───────────────────────────────────
    // Pattern: joyful ascending call-and-response
    const mel = [
      [C5, 0.18], [E5, 0.18], [G5, 0.18], [C6, 0.30],
      [B5, 0.12], [A5, 0.12], [G5, 0.30],
      [E5, 0.18], [G5, 0.18], [A5, 0.18], [C6, 0.30],
      [G5, 0.18], [E5, 0.18], [C5, 0.40],
    ];
    let mt = t;
    mel.forEach(([freq, dur]) => {
      scheduleNote(ctx, dest, freq, mt, dur, 0.55, "sine", 0.01, 0.05);
      mt += dur + 0.03;
    });

    // ── HARMONY (triangle, softer lower octave) ───────────────────────────
    const har = [
      [C4, 0.36], [E4, 0.36], [G4, 0.36], [C5, 0.30],
      [G4, 0.24], [E4, 0.30],
      [C4, 0.36], [E4, 0.36], [F5, 0.18], [C5, 0.30],
      [G4, 0.36], [C4, 0.40],
    ];
    let ht = t;
    har.forEach(([freq, dur]) => {
      scheduleNote(ctx, dest, freq, ht, dur, 0.3, "triangle", 0.02, 0.08);
      ht += dur + 0.03;
    });

    // ── BELL ACCENT (short high sine pings on beat) ───────────────────────
    const bells = [t, t + 0.72, t + 1.44, t + 2.16];
    bells.forEach(bt => scheduleNote(ctx, dest, C6 * 2, bt, 0.10, 0.4, "sine", 0.005, 0.09));

    // ── RHYTHM PULSE (sawtooth low kick feel) ─────────────────────────────
    for (let i = 0; i < 8; i++) {
      scheduleNote(ctx, dest, 80, t + i * 0.36, 0.08, 0.18, "sawtooth", 0.005, 0.07);
    }

    // Total duration ~2.8s, called every 3.2s = seamless loop

  } catch (e) { console.warn("Audio error:", e); }
}

// ─── ALARM POPUP ──────────────────────────────────────────────────────────────
function AlarmPopup({ reminder, onDismiss, onTake }) {
  const loopRef = useRef(null);
  const countRef = useRef(0);
  const [beat, setBeat] = useState(0); // drives waveform animation

  useEffect(() => {
    // Unlock audio immediately on mount (needs to run in user-interaction context)
    getAudioCtx();

    // Play first note immediately
    playAlarmSound();

    // Loop every 3.2s (melody is ~2.8s so there's a 0.4s gap between loops)
    loopRef.current = setInterval(() => {
      countRef.current += 1;
      playAlarmSound();
      setBeat(b => b + 1);
      if (countRef.current >= 25) {
        clearInterval(loopRef.current); // stop after ~80s
      }
    }, 3200);

    return () => {
      clearInterval(loopRef.current);
      stopAllAlarmSounds();
    };
  }, []);

  const stop = () => {
    clearInterval(loopRef.current);
    stopAllAlarmSounds();
  };

  const dismiss = () => { stop(); onDismiss(); };
  const take = () => { stop(); onTake(); };

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 9999,
      background: "rgba(4,8,18,0.95)",
      display: "flex", alignItems: "center", justifyContent: "center",
      animation: "fadeIn 0.25s ease",
      backdropFilter: "blur(12px)",
    }}>
      <div style={{
        background: `linear-gradient(160deg,#0F1E10,${C.card})`,
        border: `2px solid ${C.warn}88`,
        borderRadius: 28, padding: "30px 22px 24px",
        maxWidth: 310, width: "92%", textAlign: "center",
        boxShadow: `0 0 80px ${C.warn}55, 0 0 30px ${C.warn}22, 0 32px 80px #00000090`,
        animation: "fadeUp 0.35s ease",
        position: "relative", overflow: "hidden",
      }}>

        {/* Background glow pulse */}
        <div style={{ position: "absolute", inset: 0, background: `radial-gradient(ellipse at 50% 30%,${C.warn}18 0%,transparent 65%)`, pointerEvents: "none", animation: `pulse 1.6s ease-in-out infinite` }} />

        {/* Music note floating decorations */}
        {["♪", "♫", "♩", "♬"].map((n, i) => (
          <div key={i} style={{
            position: "absolute", fontSize: 18, color: `${C.warn}55`, fontWeight: 700,
            top: i < 2 ? "12%" : "75%",
            left: i % 2 === 0 ? "8%" : "82%",
            animation: `floatBg ${2.5 + i * 0.4}s ${i * 0.5}s ease-in-out infinite`,
            pointerEvents: "none",
          }}>{n}</div>
        ))}

        {/* Alarm bell icon — shakes on each beat */}
        <div key={beat} style={{ position: "relative", width: 86, height: 86, margin: "0 auto 16px" }}>
          <div style={{ position: "absolute", inset: -10, borderRadius: "50%", border: `3px solid ${C.warn}50`, animation: "ping 1s ease-out infinite" }} />
          <div style={{ position: "absolute", inset: -5, borderRadius: "50%", border: `2px solid ${C.warn}30`, animation: "ping 1s 0.4s ease-out infinite" }} />
          <div style={{
            width: 86, height: 86, borderRadius: "50%",
            background: `linear-gradient(135deg,${C.warn},#E65C00)`,
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 38,
            boxShadow: `0 0 40px ${C.warn}88, 0 8px 30px ${C.warn}44`,
            animation: "pulse 0.8s ease-in-out infinite",
          }}>🔔</div>
        </div>

        {/* MUSIC VISUALIZER — animated bars */}
        <div style={{ display: "flex", gap: 3, justifyContent: "center", alignItems: "flex-end", height: 36, marginBottom: 18 }}>
          {[8, 14, 22, 30, 18, 26, 14, 20, 28, 16, 24, 12, 20, 30, 16, 10].map((baseH, i) => {
            const phase = (beat * 3 + i) % 4;
            const heights = [baseH, baseH * 0.5, baseH * 1.2, baseH * 0.7];
            const h = Math.round(heights[phase]);
            const colors = [C.warn, C.accent, C.orange, C.warn];
            return (
              <div key={i} style={{
                width: 5, height: h,
                background: `linear-gradient(to top,${colors[i % 4]},${colors[(i + 1) % 4]})`,
                borderRadius: 3,
                transition: "height 0.25s ease",
                opacity: 0.9,
              }} />
            );
          })}
        </div>

        {/* Labels */}
        <div style={{ fontSize: 10, fontWeight: 800, color: C.warn, letterSpacing: 2, textTransform: "uppercase", marginBottom: 10 }}>
          {t.medicineAlarm}
        </div>

        <div style={{ fontSize: 24, fontWeight: 800, color: C.text, marginBottom: 4, letterSpacing: -0.3 }}>
          {reminder.name}
        </div>
        <div style={{ fontSize: 13, color: C.textSub, marginBottom: 12 }}>{reminder.dose}</div>

        <div style={{ display: "inline-flex", alignItems: "center", gap: 7, padding: "6px 18px", background: `${C.warn}20`, border: `1.5px solid ${C.warn}66`, borderRadius: 24, fontSize: 15, color: C.warn, fontWeight: 800, marginBottom: 10, letterSpacing: 0.5 }}>
          ⏰ {reminder.time}
        </div>

        <div style={{ fontSize: 12, color: C.muted, marginBottom: 22, lineHeight: 1.6 }} dangerouslySetInnerHTML={{ __html: t.alarmRinging }}>
        </div>

        {/* Buttons */}
        <div style={{ display: "flex", gap: 10 }}>
          <button
            onClick={dismiss}
            style={{ flex: 1, padding: "14px 8px", background: C.cardHover, border: `1.5px solid ${C.border}`, borderRadius: 14, color: C.textSub, fontSize: 13, fontWeight: 700, cursor: "pointer", transition: "all 0.2s", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
            onMouseEnter={e => e.currentTarget.style.borderColor = C.warn}
            onMouseLeave={e => e.currentTarget.style.borderColor = C.border}
          >
            {t.snoozeBtn}
          </button>
          <button
            onClick={take}
            style={{ flex: 1, padding: "14px 8px", background: `linear-gradient(135deg,${C.accent},#009E5A)`, border: "none", borderRadius: 14, color: "#021A0E", fontSize: 13, fontWeight: 800, cursor: "pointer", boxShadow: `0 4px 24px ${C.accentGlow}`, transition: "all 0.2s", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
            onMouseEnter={e => { e.currentTarget.style.transform = "scale(1.03)"; e.currentTarget.style.boxShadow = `0 6px 28px ${C.accentGlow}`; }}
            onMouseLeave={e => { e.currentTarget.style.transform = "scale(1)"; }}
          >
            {t.takenBtn2}
          </button>
        </div>

        {/* Tiny mute option */}
        <button onClick={stop} style={{ marginTop: 14, background: "none", border: "none", color: C.muted, fontSize: 11, cursor: "pointer", textDecoration: "underline" }}>
          {t.muteSound}
        </button>
      </div>
    </div>
  );
}

// ─── REMINDER SCREEN ──────────────────────────────────────────────────────────
function ReminderScreen() {
  const { t, lang } = useLang();

  // 1. Initial State synchronized with localStorage
  const [reminders, setReminders] = useState(() => {
    const stored = localStorage.getItem("jr_reminders");
    if (stored) {
      try { return JSON.parse(stored); } catch (e) { }
    }
    return [
      { id: 1, name: "Metformin", dose: "500mg", time: "08:00", taken: true, enabled: true },
      { id: 2, name: "Vitamin D3", dose: "1000 IU", time: "12:00", taken: false, enabled: true },
      { id: 3, name: "Aspirin", dose: "75mg", time: "21:00", taken: false, enabled: true },
      { id: 4, name: "Paracetamol", dose: "100mg", time: "07:30", taken: false, enabled: true },
    ];
  });

  // Sync to localStorage
  useEffect(() => {
    localStorage.setItem("jr_reminders", JSON.stringify(reminders));
  }, [reminders]);

  // 2. Pre-populate default history if jr_reminder_history is empty
  const [history, setHistory] = useState(() => {
    const stored = localStorage.getItem("jr_reminder_history");
    if (stored) {
      try { return JSON.parse(stored); } catch (e) { }
    }
    const defaultHistory = [
      { date: "2026-05-21", name: "Metformin", dose: "500mg", status: "Taken", timestamp: 1716300000000 },
      { date: "2026-05-21", name: "Aspirin", dose: "75mg", status: "Taken", timestamp: 1716346800000 },
      { date: "2026-05-20", name: "Metformin", dose: "500mg", status: "Taken", timestamp: 1716213600000 },
      { date: "2026-05-20", name: "Vitamin D3", dose: "1000 IU", status: "Skipped", timestamp: 1716228000000 },
      { date: "2026-05-20", name: "Aspirin", dose: "75mg", status: "Taken", timestamp: 1716260400000 },
      { date: "2026-05-19", name: "Metformin", dose: "500mg", status: "Taken", timestamp: 1716127200000 },
      { date: "2026-05-19", name: "Aspirin", dose: "75mg", status: "Taken", timestamp: 1716174000000 },
      { date: "2026-05-18", name: "Vitamin D3", dose: "1000 IU", status: "Taken", timestamp: 1716055200000 },
      { date: "2026-05-18", name: "Aspirin", dose: "75mg", status: "Skipped", timestamp: 1716087600000 },
    ];
    localStorage.setItem("jr_reminder_history", JSON.stringify(defaultHistory));
    return defaultHistory;
  });

  // 3. Pre-populate WhatsApp logs if empty
  const [waLogs, setWaLogs] = useState(() => {
    const stored = localStorage.getItem("jr_whatsapp_logs");
    if (stored) {
      try { return JSON.parse(stored); } catch (e) { }
    }
    const defaultLogs = [
      { id: 1, text: "⚠️ ALERT: Patient missed Vitamin D3 1000 IU dose. Caretaker notified.", time: "05/20, 12:05 PM" },
      { id: 2, text: "⚠️ ALERT: Patient missed Aspirin 75mg dose. Caretaker notified.", time: "05/18, 09:06 PM" },
    ];
    localStorage.setItem("jr_whatsapp_logs", JSON.stringify(defaultLogs));
    return defaultLogs;
  });

  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ name: "", dose: "", time: "" });
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({});
  const [activeAlarm, setActiveAlarm] = useState(null);
  const [currentTime, setCurrentTime] = useState(() => {
    const n = new Date();
    return String(n.getHours()).padStart(2, "0") + ":" + String(n.getMinutes()).padStart(2, "0");
  });
  const remindersRef = useRef([]);
  const snoozeRef = useRef({});
  const firedRef = useRef(new Set());
  const alarmActiveRef = useRef(false);

  useEffect(() => { remindersRef.current = reminders; }, [reminders]);

  useEffect(() => {
    const tick = () => {
      const now = new Date();
      const hh = String(now.getHours()).padStart(2, "0");
      const mm = String(now.getMinutes()).padStart(2, "0");
      const ss = now.getSeconds();
      const key = `${hh}:${mm}`;
      setCurrentTime(key);
      if (ss > 10 && ss !== 0) return;
      if (alarmActiveRef.current) return;
      remindersRef.current.forEach(r => {
        if (!r.enabled || r.taken) return;
        const snoozedUntil = snoozeRef.current[r.id];
        if (snoozedUntil && Date.now() < snoozedUntil) return;
        const fireKey = `${r.id}-${key}`;
        if (r.time === key && !firedRef.current.has(fireKey)) {
          firedRef.current.add(fireKey);
          alarmActiveRef.current = true;
          setActiveAlarm({ ...r });
          speakText(`Attention! It is time to take your dose of ${r.name} ${r.dose}.`, STT_LANG[lang] || "en-IN");
        }
      });
    };
    tick();
    const interval = setInterval(tick, 1000);
    return () => clearInterval(interval);
  }, [lang]);

  const addReminder = () => {
    if (!form.name || !form.dose || !form.time) return;
    setReminders(p => [...p, { id: Date.now(), ...form, taken: false, enabled: true }]);
    setForm({ name: "", dose: "", time: "" });
    setShowAdd(false);
  };

  const startEdit = r => { setEditingId(r.id); setEditForm({ name: r.name, dose: r.dose, time: r.time }); };
  const cancelEdit = () => { setEditingId(null); setEditForm({}); };
  const saveEdit = id => {
    if (!editForm.name || !editForm.dose || !editForm.time) return;
    setReminders(p => p.map(r => r.id === id ? { ...r, ...editForm } : r));
    firedRef.current = new Set([...firedRef.current].filter(k => !k.startsWith(`${id}-`)));
    setEditingId(null); setEditForm({});
  };

  const logAdherence = (reminder, status) => {
    const today = new Date().toISOString().split("T")[0];
    const newEntry = {
      date: today,
      name: reminder.name,
      dose: reminder.dose,
      status: status,
      timestamp: Date.now()
    };
    const updatedHistory = [newEntry, ...history];
    setHistory(updatedHistory);
    localStorage.setItem("jr_reminder_history", JSON.stringify(updatedHistory));

    if (status === "Skipped") {
      const logText = `⚠️ ALERT: Patient missed ${reminder.name} ${reminder.dose} dose. Dispatched to caretaker (+91 98765 43210)`;
      const newLog = {
        id: Date.now(),
        text: logText,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })
      };
      const updatedLogs = [newLog, ...waLogs];
      setWaLogs(updatedLogs);
      localStorage.setItem("jr_whatsapp_logs", JSON.stringify(updatedLogs));

      speakText(`Reminder skipped. Caretaker has been alerted via WhatsApp.`, STT_LANG[lang] || "en-IN");
    } else {
      speakText(`${reminder.name} taken successfully. Keep up the excellent compliance!`, STT_LANG[lang] || "en-IN");
    }
  };

  const toggleTaken = id => {
    setReminders(p => p.map(r => {
      if (r.id === id) {
        const nextTaken = !r.taken;
        logAdherence(r, nextTaken ? "Taken" : "Skipped");
        return { ...r, taken: nextTaken };
      }
      return r;
    }));
  };

  const toggleEnabled = id => setReminders(p => p.map(r => r.id === id ? { ...r, enabled: !r.enabled } : r));
  const deleteReminder = id => { setReminders(p => p.filter(r => r.id !== id)); if (editingId === id) cancelEdit(); };

  const handleDismiss = () => {
    if (activeAlarm) {
      snoozeRef.current = { ...snoozeRef.current, [activeAlarm.id]: Date.now() + 5 * 60 * 1000 };
      logAdherence(activeAlarm, "Skipped");
    }
    alarmActiveRef.current = false; setActiveAlarm(null);
  };
  const handleTake = () => {
    if (activeAlarm) {
      setReminders(p => p.map(r => r.id === activeAlarm.id ? { ...r, taken: true } : r));
      logAdherence(activeAlarm, "Taken");
    }
    alarmActiveRef.current = false; setActiveAlarm(null);
  };

  const testAlarm = r => {
    alarmActiveRef.current = true;
    setActiveAlarm({ ...r });
    speakText(`Attention! This is a test reminder for ${r.name} ${r.dose}.`, STT_LANG[lang] || "en-IN");
  };

  const taken = reminders.filter(r => r.taken).length;

  // Compliance percentage calculations
  const totalLogs = history.length;
  const takenLogs = history.filter(h => h.status === "Taken").length;
  const complianceRate = totalLogs > 0 ? Math.round((takenLogs / totalLogs) * 100) : 100;

  // Circle ring configuration
  const radius = 22;
  const circumference = 2 * Math.PI * radius;
  const strokeOffset = circumference - (complianceRate / 100) * circumference;

  const getTimeStatus = rTime => {
    const [rh, rm] = rTime.split(":").map(Number);
    const now = new Date(), then = new Date();
    then.setHours(rh, rm, 0, 0);
    if (then < now) then.setDate(then.getDate() + 1);
    const diff = Math.round((then - now) / 60000);
    if (diff === 0) return { label: t.ringing || "Ringing", color: C.warn };
    if (diff <= 5) return { label: `⚡ ${t.inText} ${diff}${t.mTime}`, color: C.danger };
    if (diff <= 30) return { label: `⏰ ${t.inText} ${diff}${t.mTime}`, color: C.accent };
    if (diff < 60) return { label: `🕐 ${t.inText} ${diff}${t.mTime}`, color: C.blue };
    const h = Math.floor(diff / 60), m = diff % 60;
    if (h < 12) return { label: `🕐 ${t.inText} ${h}${t.hTime} ${m}${t.mTime}`, color: C.textSub };
    return null;
  };

  const InlineInput = ({ label, value, onChange, type = "text", placeholder, highlight }) => {
    const [f, setF] = useState(false);
    return (
      <div style={{ marginBottom: 8 }}>
        <div style={{ fontSize: 9, fontWeight: 700, color: highlight ? C.warn : C.accent, textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 3 }}>{label}</div>
        <input type={type} value={value} onChange={e => onChange(e.target.value)}
          placeholder={placeholder}
          onFocus={() => setF(true)} onBlur={() => setF(false)}
          style={{ width: "100%", background: C.bg, border: `1.5px solid ${f ? C.accent : highlight ? C.warn + "88" : C.border}`, borderRadius: 8, padding: "8px 10px", fontSize: type === "time" ? "15px" : "13px", color: type === "time" ? C.warn : C.text, fontWeight: type === "time" ? 700 : 400, boxShadow: f ? `0 0 0 3px ${C.accentGlow}` : "none", transition: "all 0.2s" }}
        />
      </div>
    );
  };

  return (
    <>
      {activeAlarm && <AlarmPopup reminder={activeAlarm} onDismiss={handleDismiss} onTake={handleTake} />}
      <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>

        {/* Adherence Compliance Board */}
        <Card style={{ marginBottom: 14, background: `linear-gradient(135deg, ${C.cardHover}, ${C.card})`, border: `1px solid ${complianceRate > 80 ? C.accent + "33" : C.warn + "33"}`, padding: "12px 14px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            {/* SVG Adherence Ring */}
            <div style={{ position: "relative", width: 56, height: 56, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="56" height="56">
                <circle cx="28" cy="28" r={radius} fill="transparent" stroke={C.border} strokeWidth="4" />
                <circle cx="28" cy="28" r={radius} fill="transparent"
                  stroke={complianceRate > 80 ? C.accent : C.warn}
                  strokeWidth="4"
                  strokeDasharray={circumference}
                  strokeDashoffset={strokeOffset}
                  strokeLinecap="round"
                  style={{ transition: "stroke-dashoffset 0.5s ease-in-out" }}
                />
              </svg>
              <div style={{ position: "absolute", fontSize: 11, fontWeight: 800, color: C.text }}>
                {complianceRate}%
              </div>
            </div>
            {/* Health Compliance Metrics */}
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 9, fontWeight: 700, color: complianceRate > 80 ? C.accent : C.warn, textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 2 }}>Adherence Compliance Rate</div>
              <div style={{ fontSize: 13, fontWeight: 800, color: C.text }}>
                {complianceRate > 85 ? "👑 Excellent Adherence!" : complianceRate > 70 ? "📈 Stable Compliance" : "⚠️ Risk of Non-Adherence"}
              </div>
              <div style={{ fontSize: 10, color: C.textSub, marginTop: 2 }}>
                Logged: {takenLogs} Taken · {totalLogs - takenLogs} Skipped doses in history logs.
              </div>
            </div>
          </div>
        </Card>

        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 800, color: C.text }}>💊 {t.medRemindersTitle}</div>
            <div style={{ fontSize: 12, color: C.textSub, marginTop: 2 }}>{taken}/{reminders.length} {t.takenToday}</div>
          </div>
          <button onClick={() => { setShowAdd(p => !p); cancelEdit(); }}
            style={{ background: `linear-gradient(135deg,${C.accent},#009E5A)`, border: "none", borderRadius: 10, padding: "8px 14px", fontSize: 12, color: "#021A0E", cursor: "pointer", fontWeight: 700 }}>
            {showAdd ? "✕ Close" : t.addBtn}
          </button>
        </div>

        {/* Progress */}
        <div style={{ marginBottom: 12 }}>
          <div style={{ height: 5, background: C.border, borderRadius: 4, overflow: "hidden" }}>
            <div style={{ height: 5, width: `${reminders.length ? (taken / reminders.length) * 100 : 0}%`, background: `linear-gradient(90deg,${C.accent},${C.blue})`, borderRadius: 4, transition: "width 0.6s" }} />
          </div>
        </div>

        {/* Live clock */}
        <Card style={{ marginBottom: 12, padding: "10px 14px", display: "flex", alignItems: "center", justifyContent: "space-between", background: `linear-gradient(135deg,${C.cardHover},${C.card})` }}>
          <div>
            <div style={{ fontSize: 9, color: C.muted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8 }}>{t.now}</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: C.accent, letterSpacing: 2, fontVariantNumeric: "tabular-nums" }}>{currentTime || "--:--"}</div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 9, color: C.muted, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>{t.activeAlarms}</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 3, alignItems: "flex-end" }}>
              {reminders.filter(r => r.enabled && !r.taken).map(r => (
                <span key={r.id} style={{ fontSize: 10, fontWeight: 700, color: C.warn, background: `${C.warn}18`, border: `1px solid ${C.warn}33`, borderRadius: 6, padding: "2px 8px" }}>⏰ {r.time} · {r.name}</span>
              ))}
              {reminders.filter(r => r.enabled && !r.taken).length === 0 && <span style={{ fontSize: 11, color: C.accent }}>{t.allDone}</span>}
            </div>
          </div>
        </Card>

        {/* Add form */}
        {showAdd && (
          <Card style={{ marginBottom: 12, border: `1.5px solid ${C.accent}66`, background: `${C.accent}06`, animation: "fadeUp 0.3s ease" }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: C.accent, marginBottom: 12 }}>{t.addNewAlarm}</div>
            <InlineInput label="Medicine Name" value={form.name} onChange={v => setForm(p => ({ ...p, name: v }))} placeholder="e.g. Paracetamol" />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              <InlineInput label="Dosage" value={form.dose} onChange={v => setForm(p => ({ ...p, dose: v }))} placeholder="e.g. 500mg" />
              <InlineInput label="⏰ Alarm Time" type="time" value={form.time} onChange={v => setForm(p => ({ ...p, time: v }))} highlight />
            </div>
            <div style={{ fontSize: 10, color: C.muted, margin: "8px 0" }}>{t.alarmEveryDay}</div>
            <div style={{ display: "flex", gap: 8 }}>
              <Btn onClick={addReminder} small disabled={!form.name || !form.dose || !form.time}>{t.saveAlarm}</Btn>
              <Btn variant="secondary" onClick={() => setShowAdd(false)} small>{t.cancel}</Btn>
            </div>
          </Card>
        )}

        {/* Reminder cards */}
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 14 }}>
          {reminders.map((r, i) => {
            const isEditing = editingId === r.id;
            const timeStatus = getTimeStatus(r.time);
            const isSnoozed = snoozeRef.current[r.id] && Date.now() < snoozeRef.current[r.id];
            return (
              <Card key={r.id} style={{
                animation: `fadeUp 0.35s ${i * 0.06}s ease both`,
                border: `1.5px solid ${isEditing ? C.accent : r.taken ? C.accent + "44" : isSnoozed ? C.warn + "44" : C.border}`,
                background: isEditing ? `${C.accent}07` : r.taken ? `${C.accent}06` : C.card,
                transition: "border 0.2s,background 0.2s",
                padding: isEditing ? "14px" : "12px 14px",
              }}>

                {/* ── EDIT MODE ─────────────────────────────── */}
                {isEditing ? (
                  <div style={{ animation: "fadeIn 0.2s ease" }}>
                    <div style={{ fontSize: 11, fontWeight: 800, color: C.accent, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 12 }}>{t.editAlarm}</div>
                    <InlineInput label="Medicine Name" value={editForm.name} onChange={v => setEditForm(p => ({ ...p, name: v }))} placeholder="Medicine name" />
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                      <InlineInput label="Dosage" value={editForm.dose} onChange={v => setEditForm(p => ({ ...p, dose: v }))} placeholder="e.g. 500mg" />
                      <InlineInput label="⏰ Alarm Time" type="time" value={editForm.time} onChange={v => setEditForm(p => ({ ...p, time: v }))} highlight />
                    </div>
                    {editForm.time && (() => {
                      const s = getTimeStatus(editForm.time);
                      return s ? (
                        <div style={{ margin: "8px 0", padding: "7px 10px", background: `${s.color}12`, border: `1px solid ${s.color}33`, borderRadius: 8, fontSize: 11, color: s.color, fontWeight: 600 }}>
                          🔔 Will ring at <strong>{editForm.time}</strong> — {s.label}
                        </div>
                      ) : null;
                    })()}
                    <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
                      <button onClick={() => saveEdit(r.id)}
                        disabled={!editForm.name || !editForm.dose || !editForm.time}
                        style={{ flex: 1, padding: "11px", background: `linear-gradient(135deg,${C.accent},#009E5A)`, border: "none", borderRadius: 10, color: "#021A0E", fontSize: 13, fontWeight: 800, cursor: "pointer", boxShadow: `0 4px 16px ${C.accentGlow}`, opacity: (!editForm.name || !editForm.dose || !editForm.time) ? 0.4 : 1 }}>
                        {t.saveChanges}
                      </button>
                      <button onClick={cancelEdit}
                        style={{ flex: 1, padding: "11px", background: C.cardHover, border: `1.5px solid ${C.border}`, borderRadius: 10, color: C.textSub, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
                        {t.cancelBtn2}
                      </button>
                    </div>
                  </div>

                ) : (
                  /* ── VIEW MODE ──────────────────────────────── */
                  <div style={{ display: "flex", alignItems: "center", gap: 11 }}>
                    {/* Checkbox */}
                    <div onClick={() => toggleTaken(r.id)} style={{ width: 28, height: 28, borderRadius: 9, border: `2px solid ${r.taken ? C.accent : C.border}`, background: r.taken ? C.accent : "transparent", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transition: "all 0.2s", boxShadow: r.taken ? `0 0 10px ${C.accentGlow}` : "none" }}>
                      {r.taken && <span style={{ fontSize: 14, color: "#021A0E", fontWeight: 900 }}>✓</span>}
                    </div>
                    {/* Info */}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, color: C.text, textDecoration: r.taken ? "line-through" : "none", opacity: r.taken ? 0.55 : 1 }}>{r.name}</div>
                      <div style={{ fontSize: 11, color: C.muted, marginTop: 2, display: "flex", alignItems: "center", gap: 5 }}>
                        <span>{r.dose}</span><span>·</span>
                        <span style={{ color: C.warn, fontWeight: 700 }}>⏰ {r.time}</span>
                        {isSnoozed && <span style={{ color: C.warn, fontWeight: 600 }}>💤</span>}
                      </div>
                      {timeStatus && !r.taken && r.enabled && (
                        <span style={{ marginTop: 4, display: "inline-block", fontSize: 10, fontWeight: 700, color: timeStatus.color, background: `${timeStatus.color}18`, border: `1px solid ${timeStatus.color}33`, borderRadius: 6, padding: "2px 7px" }}>
                          {timeStatus.label}
                        </span>
                      )}
                    </div>
                    {/* Controls */}
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6, flexShrink: 0 }}>
                      <Badge color={r.taken ? C.accent : isSnoozed ? C.warn : r.enabled ? C.blue : C.muted}>
                        {r.taken ? t.takenBadge || "Taken" : isSnoozed ? t.snoozedBadge || "Snoozed" : r.enabled ? t.activeBadge || "Active" : t.offBadge || "Off"}
                      </Badge>
                      <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
                        {/* Edit */}
                        <button onClick={() => startEdit(r)} title="Edit alarm"
                          style={{ background: `${C.blue}18`, border: `1px solid ${C.blue}33`, borderRadius: 7, width: 26, height: 26, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={C.blue} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
                            <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
                          </svg>
                        </button>
                        {/* Test */}
                        {!r.taken && r.enabled && (
                          <button onClick={() => testAlarm(r)} title="Test alarm"
                            style={{ background: `${C.warn}18`, border: `1px solid ${C.warn}33`, borderRadius: 7, width: 26, height: 26, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12 }}>🔔</button>
                        )}
                        {/* Toggle */}
                        <div onClick={() => toggleEnabled(r.id)} style={{ width: 34, height: 18, borderRadius: 9, background: r.enabled ? C.accent : C.border, position: "relative", cursor: "pointer", transition: "background 0.3s", flexShrink: 0 }}>
                          <div style={{ position: "absolute", top: 2, left: r.enabled ? "18px" : "2px", width: 14, height: 14, borderRadius: "50%", background: "#fff", transition: "left 0.3s", boxShadow: "0 1px 4px #0004" }} />
                        </div>
                        {/* Delete */}
                        <button onClick={() => deleteReminder(r.id)} title="Delete"
                          style={{ background: `${C.danger}18`, border: `1px solid ${C.danger}33`, borderRadius: 7, width: 26, height: 26, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, color: C.danger }}>✕</button>
                      </div>
                    </div>
                  </div>
                )}
              </Card>
            );
          })}
        </div>

        {reminders.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 20px", color: C.muted }}>
            <div style={{ fontSize: 40, marginBottom: 10 }}>💊</div>
            <div style={{ fontSize: 14, fontWeight: 600, color: C.textSub }}>{t.noReminders}</div>
            <div style={{ fontSize: 12, marginTop: 4 }}>{t.tapToAddAlarm}</div>
          </div>
        )}

        {/* Caretaker Telemetry Alerts Board */}
        <Divider label="Caretaker Notification Telemetry" />
        <Card style={{ background: "#050c18", border: "1px solid #1a2f4c", padding: "12px 14px", borderRadius: 12 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid #1a2f4c", paddingBottom: 6, marginBottom: 8 }}>
            <span style={{ fontSize: 10, color: "#9ab", fontWeight: 800 }}>📲 WHATSAPP GUARDIAN BRIDGE LOGS</span>
            <span style={{ fontSize: 8, color: C.accent }}>● ONLINE CONNECTED</span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 110, overflowY: "auto" }}>
            {waLogs.map((log) => (
              <div key={log.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, fontSize: 10.5, fontFamily: "monospace", color: "#a8c3e8", animation: "fadeIn 0.2s ease" }}>
                <span>{log.text}</span>
                <span style={{ flexShrink: 0, color: "#678", fontSize: 9 }}>{log.time}</span>
              </div>
            ))}
            {waLogs.length === 0 && (
              <div style={{ textShadow: "none", color: "#567", fontSize: 11, textAlign: "center", fontFamily: "monospace", padding: "10px 0" }}>No missed dosages logged yet. Excellent compliance streak!</div>
            )}
          </div>
        </Card>

        <div style={{ height: 12 }} />
      </div>
    </>
  );
}


