function LibraryScreen() {
  const { t, lang } = useLang();
  const library = LIBRARY_DATA[lang] || LIBRARY_DATA.English;
  const [sel, setSel] = useState(null);
  if (sel !== null) {
    const ti = library[sel] || LIBRARY_DATA.English[sel];
    return (
      <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>
        <button onClick={() => setSel(null)} style={{ background: "none", border: "none", color: C.textSub, fontSize: 13, cursor: "pointer", marginBottom: 14, display: "flex", alignItems: "center", gap: 5 }}>{t.backToLibrary}</button>
        <div style={{ animation: "fadeUp 0.4s ease" }}>
          <div style={{ width: 52, height: 52, borderRadius: 16, background: `${ti.color}20`, border: `1px solid ${ti.color}44`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 24, marginBottom: 12 }}>{ti.icon}</div>
          <div style={{ fontSize: 18, fontWeight: 800, color: C.text, marginBottom: 6 }}>{ti.title}</div>
          <div style={{ fontSize: 13, color: C.textSub, marginBottom: 18, lineHeight: 1.6 }}>{ti.desc}</div>
          <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 10 }}>{t.keyTips}</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {ti.tips.map((tip, i) => (
              <Card key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", animation: `fadeUp 0.4s ${i * 0.08}s ease both` }}>
                <div style={{ width: 22, height: 22, borderRadius: 6, background: `${ti.color}20`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, color: ti.color, fontWeight: 800, flexShrink: 0 }}>{i + 1}</div>
                <div style={{ fontSize: 13, color: C.text }}>{tip}</div>
              </Card>
            ))}
          </div>
        </div>
      </div>
    );
  }
  const displayLibrary = LIBRARY_DATA[lang] || LIBRARY_DATA.English;
  return (
    <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>
      <div style={{ fontSize: 16, fontWeight: 800, color: C.text, marginBottom: 4 }}>📚 {t.healthLibraryTitle}</div>
      <div style={{ fontSize: 12, color: C.textSub, marginBottom: 16 }}>{t.evidenceBased}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {displayLibrary.map((ti, i) => (
          <Card key={i} onClick={() => setSel(i)} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer", animation: `fadeUp 0.4s ${i * 0.07}s ease both` }}
            onMouseEnter={e => e.currentTarget.style.borderColor = ti.color + "66"} onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
            <div style={{ width: 44, height: 44, borderRadius: 13, background: `${ti.color}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, border: `1px solid ${ti.color}30`, flexShrink: 0 }}>{ti.icon}</div>
            <div style={{ flex: 1 }}><div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{ti.title}</div><div style={{ fontSize: 11, color: C.muted, marginTop: 2, lineHeight: 1.4 }}>{ti.desc}</div></div>
            <span style={{ color: C.muted, fontSize: 16 }}>›</span>
          </Card>
        ))}
      </div>
    </div>
  );
}

// ─── PROFILE ──────────────────────────────────────────────────────────────────
function ProfileScreen({ username, userEmail, onLogout }) {
  const { t, lang, setLang } = useLang();
  const [profile, setProfile] = useState({ age: "28", gender: "male", blood: "B+", allergies: "Penicillin", conditions: "None", emergency: "9876543210", language: lang });
  const [editing, setEditing] = useState(false);
  const [saved, setSaved] = useState(false);

  // Modals
  const [modal, setModal] = useState(null); // "password" | "delete" | "privacy" | "export"

  // Change password state
  const [pwForm, setPwForm] = useState({ old: "", newP: "", confirm: "" });
  const [pwErrors, setPwErrors] = useState({});
  const [pwSuccess, setPwSuccess] = useState(false);

  // Delete account state
  const [deleteConfirm, setDeleteConfirm] = useState("");
  const [deleteStep, setDeleteStep] = useState(1);

  const set = (k, v) => setProfile(p => ({ ...p, [k]: v }));

  const save = () => {
    if (profile.language && profile.language !== lang) setLang(profile.language);
    setEditing(false); setSaved(true); setTimeout(() => setSaved(false), 2500);
  };

  // ── Change Password ──────────────────────────────────────────────────────
  const handleChangePassword = async () => {
    const e = {};
    if (!pwForm.old) e.old = "Current password required";
    else if (pwForm.old.length < 6) e.old = "Min 6 characters";
    if (!pwForm.newP) e.newP = "New password required";
    else if (pwForm.newP.length < 8) e.newP = "Min 8 characters";
    if (pwForm.newP !== pwForm.confirm) e.confirm = "Passwords don't match";
    if (Object.keys(e).length) { setPwErrors(e); return; }

    try {
      const key = `jr_account_${userEmail?.toLowerCase().trim() || ""}`;
      const raw = localStorage.getItem(key);
      if (raw) {
        const account = JSON.parse(raw);
        if (account.password !== pwForm.old) {
          setPwErrors({ old: "Incorrect current password." });
          return;
        }
        account.password = pwForm.newP;
        localStorage.setItem(key, JSON.stringify(account));
      }
    } catch (_) { }

    setPwErrors({});
    setPwSuccess(true);
    setTimeout(() => { setPwSuccess(false); setModal(null); setPwForm({ old: "", newP: "", confirm: "" }); }, 2000);
  };

  // ── Export Data ──────────────────────────────────────────────────────────
  const handleExport = () => {
    const data = {
      exportedAt: new Date().toISOString(),
      username,
      profile,
      app: "Jeeva Raksha",
      version: "1.0",
      note: "This file contains your personal health data from Jeeva Raksha app."
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `JeevaRaksha_${username}_data.json`;
    a.click();
    URL.revokeObjectURL(url);
    setModal(null);
  };

  // ── Delete Account ───────────────────────────────────────────────────────
  const handleDelete = () => {
    if (deleteStep === 1) { setDeleteStep(2); return; }
    if (deleteConfirm.toLowerCase() !== "delete") return;
    onLogout();
  };

  // ── Modal overlay ────────────────────────────────────────────────────────
  const Modal = ({ title, onClose, children }) => (
    <div style={{ position: "fixed", inset: 0, zIndex: 9000, background: "rgba(4,8,18,0.92)", display: "flex", alignItems: "flex-end", justifyContent: "center", animation: "fadeIn 0.2s ease", backdropFilter: "blur(8px)" }}>
      <div style={{ width: "100%", maxWidth: 420, background: C.card, borderRadius: "22px 22px 0 0", border: `1px solid ${C.border}`, borderBottom: "none", padding: "20px 20px 32px", maxHeight: "88vh", overflowY: "auto", animation: "fadeUp 0.3s ease" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 18 }}>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.text }}>{title}</div>
          <button onClick={onClose} style={{ background: C.cardHover, border: `1px solid ${C.border}`, borderRadius: 8, width: 30, height: 30, cursor: "pointer", fontSize: 16, color: C.textSub, display: "flex", alignItems: "center", justifyContent: "center" }}>✕</button>
        </div>
        {children}
      </div>
    </div>
  );

  return (
    <>
      {/* ── CHANGE PASSWORD MODAL ─────────────────────────────────────── */}
      {modal === "password" && (
        <Modal title={t.changePasswordModal} onClose={() => { setModal(null); setPwForm({ old: "", newP: "", confirm: "" }); setPwErrors({}); setPwSuccess(false); }}>
          {pwSuccess ? (
            <div style={{ textAlign: "center", padding: "20px 0" }}>
              <div style={{ fontSize: 48, marginBottom: 12 }}>✅</div>
              <div style={{ fontSize: 16, fontWeight: 700, color: C.accent }}>{t.passwordChanged}</div>
              <div style={{ fontSize: 12, color: C.muted, marginTop: 6 }}>{t.passwordUpdated}</div>
            </div>
          ) : (
            <>
              <div style={{ padding: "10px 14px", background: `${C.blue}12`, border: `1px solid ${C.blue}30`, borderRadius: 10, fontSize: 12, color: C.textSub, marginBottom: 16, lineHeight: 1.5 }}>
                {t.securityHint}
              </div>
              <Field label={t.currentPassword} type="password" value={pwForm.old} onChange={v => { setPwForm(p => ({ ...p, old: v })); setPwErrors(p => ({ ...p, old: "" })); }} placeholder="Enter current password" icon="🔒" error={pwErrors.old} />
              <Field label={t.newPassword} type="password" value={pwForm.newP} onChange={v => { setPwForm(p => ({ ...p, newP: v })); setPwErrors(p => ({ ...p, newP: "" })); }} placeholder="Min 8 characters" icon="🔑" error={pwErrors.newP} />
              {/* {t.passwordStrength} */}
              {pwForm.newP.length > 0 && (
                <div style={{ marginTop: -8, marginBottom: 12 }}>
                  <div style={{ height: 4, background: C.border, borderRadius: 4, overflow: "hidden" }}>
                    <div style={{
                      height: 4, borderRadius: 4, transition: "width 0.4s,background 0.4s",
                      width: pwForm.newP.length < 6 ? "30%" : pwForm.newP.length < 10 ? "62%" : "100%",
                      background: pwForm.newP.length < 6 ? C.danger : pwForm.newP.length < 10 ? C.warn : C.accent
                    }} />
                  </div>
                  <div style={{ fontSize: 10, color: pwForm.newP.length < 6 ? C.danger : pwForm.newP.length < 10 ? C.warn : C.accent, marginTop: 3, fontWeight: 600 }}>
                    {pwForm.newP.length < 6 ? "Weak" : pwForm.newP.length < 10 ? "Fair" : "Strong 💪"}
                  </div>
                </div>
              )}
              <Field label={t.confirmNewPassword} type="password" value={pwForm.confirm} onChange={v => { setPwForm(p => ({ ...p, confirm: v })); setPwErrors(p => ({ ...p, confirm: "" })); }} placeholder="Re-enter new password" icon="🔑" error={pwErrors.confirm} />
              <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
                <Btn onClick={handleChangePassword}>{t.updatePasswordBtn}</Btn>
              </div>
              <Btn variant="secondary" onClick={() => { setModal(null); setPwForm({ old: "", newP: "", confirm: "" }); setPwErrors({}); }}>{t.cancelBtn}</Btn>
            </>
          )}
        </Modal>
      )}

      {/* ── PRIVACY POLICY MODAL ──────────────────────────────────────── */}
      {modal === "privacy" && (
        <Modal title={t.privacyPolicyModal} onClose={() => setModal(null)}>
          {[
            { title: "1. Data We Collect", icon: "📊", body: "We collect your name, email, phone number, health profile information (age, gender, blood group, allergies, medical conditions), and medicine reminders that you voluntarily provide." },
            { title: "2. How We Use Your Data", icon: "🎯", body: "Your data is used solely to provide personalized health guidance, medicine reminders, and emergency assistance features within the Jeeva Raksha app. We do not sell your data." },
            { title: "3. Data Storage & Security", icon: "🔐", body: "All data is stored securely using Firebase with end-to-end encryption. Your health information is encrypted at rest and in transit using industry-standard AES-256 encryption." },
            { title: "4. Third-Party Services", icon: "🤝", body: "We use Firebase Authentication (Google) for secure login, Anthropic Claude AI for health chat (conversations are not stored), and OpenStreetMap for hospital data." },
            { title: "5. Your Rights", icon: "⚖️", body: "You have the right to access, edit, export, or permanently delete your data at any time through the Profile settings. You may also withdraw consent by deleting your account." },
            { title: "6. Health Data Disclaimer", icon: "⚕️", body: "Jeeva Raksha provides general health information only. It is not a substitute for professional medical advice, diagnosis, or treatment. Always consult a qualified doctor for medical decisions." },
            { title: "7. Contact Us", icon: "📧", body: "For privacy concerns or data requests, contact us at: privacy@jeevaraksha.in or write to: Jeeva Raksha Health Tech, Bengaluru, Karnataka, India." },
          ].map((s, i) => (
            <div key={i} style={{ marginBottom: 16, padding: "12px 14px", background: C.cardHover, borderRadius: 12, border: `1px solid ${C.border}` }}>
              <div style={{ fontSize: 12, fontWeight: 700, color: C.accent, marginBottom: 5 }}>{s.icon} {s.title}</div>
              <div style={{ fontSize: 12, color: C.textSub, lineHeight: 1.65 }}>{s.body}</div>
            </div>
          ))}
          <div style={{ padding: "10px 14px", background: `${C.accent}10`, border: `1px solid ${C.accentGlow}`, borderRadius: 10, fontSize: 11, color: C.muted, textAlign: "center", marginTop: 4 }}>
            Last updated: April 2025 · Version 1.0
          </div>
          <div style={{ height: 8 }} />
          <Btn onClick={() => setModal(null)}>{t.closeBtn}</Btn>
        </Modal>
      )}

      {/* ── EXPORT DATA MODAL ─────────────────────────────────────────── */}
      {modal === "export" && (
        <Modal title={t.exportDataModal} onClose={() => setModal(null)}>
          <div style={{ textAlign: "center", padding: "10px 0 20px" }}>
            <div style={{ fontSize: 52, marginBottom: 14 }}>📦</div>
            <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 8 }}>{t.downloadData}</div>
            <div style={{ fontSize: 12, color: C.textSub, lineHeight: 1.6, marginBottom: 20 }} dangerouslySetInnerHTML={{ __html: t.exportDataInfo.replace("JSON file", `<strong style="color:${C.accent}">JSON file</strong>`) }}></div>

            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 24, textAlign: "left" }}>
              {["👤 Personal profile (age, gender, blood group)", "⚕️ Medical conditions & allergies", "📞 Emergency contact", "🌐 Language preference", "📅 Export timestamp"].map((item, i) => (
                <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", background: C.cardHover, borderRadius: 9, border: `1px solid ${C.border}`, fontSize: 12, color: C.textSub }}>
                  {item}
                </div>
              ))}
            </div>
          </div>
          <Btn onClick={handleExport}>{t.downloadJsonBtn}</Btn>
          <div style={{ height: 8 }} />
          <Btn variant="secondary" onClick={() => setModal(null)}>{t.cancelBtn}</Btn>
        </Modal>
      )}

      {/* ── DELETE ACCOUNT MODAL ──────────────────────────────────────── */}
      {modal === "delete" && (
        <Modal title={t.deleteAccountModal} onClose={() => { setModal(null); setDeleteStep(1); setDeleteConfirm(""); }}>
          {deleteStep === 1 ? (
            <>
              <div style={{ padding: "14px", background: `${C.danger}12`, border: `1px solid ${C.danger}44`, borderRadius: 12, marginBottom: 20 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: C.danger, marginBottom: 8 }}>{t.deleteWarning}</div>
                <div style={{ fontSize: 12, color: C.textSub, lineHeight: 1.6 }} dangerouslySetInnerHTML={{ __html: t.deleteInfo }}></div>
              </div>

              <div style={{ display: "flex", gap: 8 }}>
                <Btn variant="secondary" onClick={() => { setModal(null); setDeleteStep(1); }}>{t.cancelBtn}</Btn>
                <Btn variant="danger" onClick={() => setDeleteStep(2)}>{t.continueBtn}</Btn>
              </div>
            </>
          ) : (
            <>
              <div style={{ padding: "12px 14px", background: `${C.danger}10`, border: `1px solid ${C.danger}33`, borderRadius: 10, marginBottom: 16, fontSize: 12, color: C.textSub, lineHeight: 1.5 }} dangerouslySetInnerHTML={{ __html: t.typeDelete.replace("delete", `<strong style="color:${C.danger}">delete</strong>`) }}></div>

              <Field
                value={deleteConfirm}
                onChange={setDeleteConfirm}
                placeholder='Type "delete" to confirm'
                icon="⚠️"
                error={deleteConfirm && deleteConfirm.toLowerCase() !== "delete" ? "Type exactly: delete" : ""}
              />
              <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
                <Btn variant="secondary" onClick={() => { setDeleteStep(1); setDeleteConfirm(""); }}>{t.backBtnModal}</Btn>
                <Btn variant="danger" onClick={handleDelete} disabled={deleteConfirm.toLowerCase() !== "delete"}>
                  {t.deleteForever}
                </Btn>
              </div>
            </>
          )}
        </Modal>
      )}

      {/* ── MAIN PROFILE PAGE ─────────────────────────────────────────── */}
      <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>

        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
          <div style={{ width: 56, height: 56, borderRadius: 18, background: `linear-gradient(135deg,${C.blue},${C.purple})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 26, flexShrink: 0, boxShadow: `0 4px 16px ${C.purple}44` }}>👤</div>
          <div>
            <div style={{ fontSize: 17, fontWeight: 800, color: C.text }}>{username}</div>
            <div style={{ fontSize: 12, color: C.textSub }}>{t.firebaseVerified}</div>
            <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 3 }}>
              <div style={{ width: 6, height: 6, borderRadius: "50%", background: C.accent, boxShadow: `0 0 6px ${C.accent}` }} />
              <span style={{ fontSize: 10, color: C.accent, fontWeight: 600 }}>{t.activeAccountLabel}</span>
            </div>
          </div>
          <button onClick={() => setEditing(p => !p)} style={{ marginLeft: "auto", background: editing ? `${C.accent}18` : C.card, border: `1px solid ${editing ? C.accent : C.border}`, borderRadius: 8, padding: "7px 12px", fontSize: 12, color: editing ? C.accent : C.textSub, cursor: "pointer", fontWeight: 600, flexShrink: 0 }}>
            {editing ? t.cancelEdit : t.edit}
          </button>
        </div>

        {/* Save success banner */}
        {saved && (
          <div style={{ padding: "9px 14px", background: `${C.accent}18`, border: `1px solid ${C.accentGlow}`, borderRadius: 10, fontSize: 12, color: C.accent, marginBottom: 12, textAlign: "center", animation: "fadeIn 0.3s ease" }}>
            ✅ {t.savedFirestore}
          </div>
        )}

        <Divider label={t.myHealthProfile} />

        {/* Profile fields */}
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 4 }}>
          {editing ? (<>
            <Field label={t.age} value={profile.age} onChange={v => set("age", v)} placeholder={t.age} icon="🎂" />
            <Field label={t.gender} type="select" value={profile.gender} onChange={v => set("gender", v)} icon="⚧️" options={[{ value: "male", label: t.male }, { value: "female", label: t.female }, { value: "other", label: t.other }]} />
            <Field label={t.bloodGroup} type="select" value={profile.blood} onChange={v => set("blood", v)} icon="🩸" options={["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"]} />
            <Field label={t.allergies} value={profile.allergies} onChange={v => set("allergies", v)} placeholder={t.allergies} icon="⚠️" />
            <Field label={t.conditions} value={profile.conditions} onChange={v => set("conditions", v)} placeholder={t.conditions} icon="🏥" />
            <Field label={t.emergencyContact} type="tel" value={profile.emergency} onChange={v => set("emergency", v)} placeholder={t.phonePlaceholder} icon="📞" />
            <Field label={t.language} type="select" value={profile.language} onChange={v => set("language", v)} icon="🌐" options={LANG_NAMES.map(l => ({ value: l, label: l }))} />
            <Btn onClick={save}>{t.saveFirestore}</Btn>
          </>) : (
            [[" 🎂", t.age, profile.age], [" ⚧️", t.gender, profile.gender], ["🩸", t.bloodGroup, profile.blood], ["⚠️", t.allergies, profile.allergies], ["🏥", t.conditions, profile.conditions], ["📞", t.emergencyContact, profile.emergency], ["🌐", t.language, profile.language]].map(([icon, label, val], i) => (
              <Card key={i} style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 14px" }}>
                <span style={{ fontSize: 18 }}>{icon}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 10, color: C.muted, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4 }}>{label}</div>
                  <div style={{ fontSize: 13, color: C.text, fontWeight: 600, marginTop: 1 }}>{val || "—"}</div>
                </div>
              </Card>
            ))
          )}
        </div>

        <Divider label={t.accountSecurity} />

        {/* Account actions — all working */}
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>

          {/* Change Password */}
          <Card onClick={() => setModal("password")} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer", padding: "13px 14px" }}
            onMouseEnter={e => e.currentTarget.style.borderColor = C.accent + "66"}
            onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: `${C.textSub}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>🔒</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{t.changePassword}</div>
              <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{t.updatePasswordDesc}</div>
            </div>
            <span style={{ color: C.muted, fontSize: 18 }}>›</span>
          </Card>

          {/* Export Data */}
          <Card onClick={() => setModal("export")} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer", padding: "13px 14px" }}
            onMouseEnter={e => e.currentTarget.style.borderColor = C.blue + "66"}
            onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: `${C.blue}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>📤</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.blue }}>{t.exportData}</div>
              <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{t.exportDataDesc}</div>
            </div>
            <span style={{ color: C.muted, fontSize: 18 }}>›</span>
          </Card>

          {/* Privacy Policy */}
          <Card onClick={() => setModal("privacy")} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer", padding: "13px 14px" }}
            onMouseEnter={e => e.currentTarget.style.borderColor = C.teal + "66"}
            onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: `${C.teal}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>📋</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{t.privacyPolicy}</div>
              <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{t.privacyDesc}</div>
            </div>
            <span style={{ color: C.muted, fontSize: 18 }}>›</span>
          </Card>

          {/* Delete Account */}
          <Card onClick={() => { setModal("delete"); setDeleteStep(1); setDeleteConfirm(""); }} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer", padding: "13px 14px", border: `1px solid ${C.danger}33` }}
            onMouseEnter={e => e.currentTarget.style.borderColor = C.danger + "88"}
            onMouseLeave={e => e.currentTarget.style.borderColor = `${C.danger}33`}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: `${C.danger}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>🗑️</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.danger }}>{t.deleteAccount}</div>
              <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>{t.deleteAccountDesc}</div>
            </div>
            <span style={{ color: C.danger, fontSize: 18 }}>›</span>
          </Card>
        </div>

        {/* Sign Out */}
        <Btn variant="danger" onClick={onLogout}>{t.signOut}</Btn>

        <div style={{ marginTop: 16, padding: "10px 14px", background: C.card, borderRadius: 10, border: `1px solid ${C.border}`, fontSize: 10, color: C.muted, textAlign: "center", lineHeight: 1.6 }}>
          {t.encryptedPrivate}
        </div>
        <div style={{ height: 16 }} />
      </div>
    </>
  );
}

// ─── 1. AYURVEDA + MODERN MEDICINE AI ────────────────────────────────────────
const AYUR_HERBS = [
  { name: "Tulsi (Holy Basil)", icon: "🌿", use: "Cold, fever, immunity", dosha: "Tridoshic" },
  { name: "Ashwagandha", icon: "🌱", use: "Stress, weakness, sleep", dosha: "Vata-Kapha" },
  { name: "Turmeric (Haldi)", icon: "🟡", use: "Inflammation, wounds, digestion", dosha: "Tridoshic" },
  { name: "Ginger (Adrak)", icon: "🫚", use: "Nausea, cold, digestion", dosha: "Vata-Kapha" },
  { name: "Neem", icon: "🍃", use: "Skin, blood purifier, diabetes", dosha: "Pitta-Kapha" },
  { name: "Amla (Gooseberry)", icon: "🟢", use: "Immunity, hair, digestion", dosha: "Tridoshic" },
];

const AYUR_SUGG = [
  { icon: "🤒", text: "Natural remedy for fever and cold?" },
  { icon: "🤢", text: "Ayurvedic cure for stomach pain?" },
  { icon: "😴", text: "Herbs to sleep better?" },
  { icon: "💪", text: "Ayurveda for weakness and fatigue?" },
  { icon: "🩸", text: "Natural blood sugar control?" },
  { icon: "🧠", text: "Herbs for memory and focus?" },
];

function AyurvedaScreen() {
  const { t, lang } = useLang();
  const [messages, setMessages] = useState([{
    id: 1, role: "assistant",
    time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    content: `🌿 ${t.vaidyaBotIntro}\n\nAsk me about any health concern!`
  }]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [tab, setTab] = useState("chat"); // chat | herbs
  const bottomRef = useRef(null);
  const ttsLang = TTS_LANG[lang] || "en-IN";

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, isTyping]);

  const sendMessage = async (text) => {
    const content = (text || input).trim(); if (!content) return;
    const time = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    setMessages(prev => [...prev, { id: Date.now(), role: "user", content, time }]);
    setInput(""); setIsTyping(true);
    try {
      const res = await fetch(`http://${window.location.hostname}:3001/api/chat`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: content, language: LANG_TO_API[lang] || lang, isAyurveda: true })
      });
      const data = await res.json();
      const botContent = data.response || "Please try again.";
      setMessages(prev => [...prev, { id: Date.now() + 1, role: "assistant", content: botContent, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }]);
    } catch {
      setMessages(prev => [...prev, { id: Date.now() + 1, role: "assistant", content: "⚠️ Connection error. Please try again.", time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }]);
    } finally { setIsTyping(false); }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
      {/* Header */}
      <div style={{ padding: "12px 16px", background: `linear-gradient(135deg,#1A2E0A,#0C1825)`, borderBottom: `1px solid #2D4A1A`, flexShrink: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ width: 38, height: 38, borderRadius: 12, background: "linear-gradient(135deg,#4CAF50,#2E7D32)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>🌿</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 14, fontWeight: 800, color: C.text }}>{t.vaidyaBot}</div>
            <div style={{ fontSize: 10, color: "#81C784" }}>{t.ayurvedaModern}</div>
          </div>
          <div style={{ display: "flex", gap: 1, background: C.card, borderRadius: 10, padding: 3, border: `1px solid ${C.border}` }}>
            {["chat", "herbs"].map(tb => (
              <button key={tb} onClick={() => setTab(tb)} style={{ padding: "5px 10px", borderRadius: 7, border: "none", background: tab === tb ? "#4CAF50" : "transparent", color: tab === tb ? "#fff" : C.muted, fontSize: 11, cursor: "pointer", fontWeight: 700, transition: "all 0.2s" }}>
                {tb === "chat" ? t.chatTab : t.herbsTab}
              </button>
            ))}
          </div>
        </div>
      </div>

      {tab === "herbs" ? (
        <div style={{ flex: 1, overflowY: "auto", padding: "14px 16px" }}>
          <div style={{ fontSize: 12, color: C.textSub, marginBottom: 14, lineHeight: 1.5 }}>
            {t.ayurHerbsInfo}
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {AYUR_HERBS.map((h, i) => (
              <Card key={i} onClick={() => { setTab("chat"); sendMessage(`Tell me about ${h.name} — its Ayurvedic uses and what modern medicine says about it`); }}
                style={{ cursor: "pointer", display: "flex", gap: 12, alignItems: "center", animation: `fadeUp 0.4s ${i * 0.07}s ease both` }}
                onMouseEnter={e => e.currentTarget.style.borderColor = "#4CAF5066"}
                onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
                <div style={{ width: 44, height: 44, borderRadius: 12, background: "#1B5E2018", border: "1px solid #4CAF5030", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, flexShrink: 0 }}>{h.icon}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{h.name}</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{h.use}</div>
                </div>
                <span style={{ fontSize: 10, padding: "3px 8px", background: "#4CAF5018", border: "1px solid #4CAF5044", borderRadius: 10, color: "#81C784", fontWeight: 600 }}>{h.dosha}</span>
              </Card>
            ))}
          </div>
        </div>
      ) : (
        <>
          <div style={{ flex: 1, overflowY: "auto", padding: "12px 14px 8px" }}>
            <div style={{ textAlign: "center", marginBottom: 12 }}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "4px 12px", background: "#1B5E2020", border: "1px solid #4CAF5044", borderRadius: 20, fontSize: 10, color: "#81C784" }}>
                {t.ancientWisdom}
              </span>
            </div>
            {messages.map(msg => {
              const isUser = msg.role === "user";
              return (
                <div key={msg.id} style={{ display: "flex", flexDirection: isUser ? "row-reverse" : "row", gap: 9, marginBottom: 14, animation: "msgIn 0.3s ease both" }}>
                  {!isUser && <div style={{ width: 32, height: 32, borderRadius: 10, background: "linear-gradient(135deg,#4CAF50,#2E7D32)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, flexShrink: 0, marginTop: 2 }}>🌿</div>}
                  <div style={{ maxWidth: "80%", display: "flex", flexDirection: "column", alignItems: isUser ? "flex-end" : "flex-start" }}>
                    <div style={{ padding: "11px 14px", borderRadius: isUser ? "14px 14px 3px 14px" : "14px 14px 14px 3px", background: isUser ? `linear-gradient(135deg,${C.blue}22,${C.accent}18)` : "#0A1E0A", border: `1.5px solid ${isUser ? C.blue + "33" : "#2D4A1A"}`, fontSize: 13, color: C.text, lineHeight: 1.7, whiteSpace: "pre-wrap" }}>{msg.content}</div>
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
                      <div style={{ fontSize: 10, color: C.muted }}>{msg.time}</div>
                      {!isUser && (
                        <button onClick={() => speakText(msg.content, ttsLang)} style={{ background: "transparent", border: "none", cursor: "pointer", fontSize: 12, opacity: 0.5, padding: 0 }} title="Read aloud">🔊</button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
            {isTyping && (
              <div style={{ display: "flex", gap: 9, marginBottom: 14 }}>
                <div style={{ width: 32, height: 32, borderRadius: 10, background: "linear-gradient(135deg,#4CAF50,#2E7D32)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15 }}>🌿</div>
                <div style={{ padding: "11px 14px", background: "#0A1E0A", border: "1.5px solid #2D4A1A", borderRadius: "14px 14px 14px 3px" }}><TypingDots /></div>
              </div>
            )}
            {messages.length === 1 && !isTyping && (
              <div style={{ marginTop: 4 }}>
                <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 8 }}>Ask {t.vaidyaBot}</div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>
                  {AYUR_SUGG.map((s, i) => (
                    <button key={i} onClick={() => sendMessage(s.text)} style={{ display: "flex", alignItems: "center", gap: 5, padding: "7px 11px", background: C.card, border: "1.5px solid #2D4A1A", borderRadius: 20, fontSize: 11, color: C.textSub, cursor: "pointer" }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor = "#4CAF50"; e.currentTarget.style.color = "#81C784"; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor = "#2D4A1A"; e.currentTarget.style.color = C.textSub; }}>
                      <span>{s.icon}</span><span>{s.text}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
            <div ref={bottomRef} />
          </div>
          <div style={{ padding: "10px 12px 12px", background: C.card, borderTop: `1px solid ${C.border}`, flexShrink: 0 }}>
            <div style={{ display: "flex", gap: 7, alignItems: "flex-end" }}>
              <MicButton onResult={t => setInput(p => p ? p + " " + t : t)} lang={lang} disabled={isTyping} />
              <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
                placeholder={t.ayurAskPlaceholder} rows={1}
                style={{ flex: 1, background: C.cardHover, border: `1.5px solid ${input ? "#4CAF50" : C.border}`, borderRadius: 12, padding: "11px 14px", fontSize: 13, color: C.text, resize: "none", lineHeight: 1.5, maxHeight: 90, overflow: "auto", transition: "border-color 0.2s", boxShadow: input ? "0 0 0 3px #4CAF5022" : "none" }} />
              <button onClick={() => sendMessage()} disabled={!input.trim() || isTyping}
                style={{ width: 44, height: 44, borderRadius: 12, border: "none", background: input.trim() && !isTyping ? "linear-gradient(135deg,#4CAF50,#2E7D32)" : C.cardHover, cursor: input.trim() && !isTyping ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 17, transition: "all 0.2s", flexShrink: 0 }}>
                {isTyping ? <div style={{ width: 14, height: 14, borderRadius: "50%", border: "2px solid #2D4A1A", borderTopColor: "#4CAF50", animation: "spin 0.7s linear infinite" }} /> : <span style={{ color: input.trim() ? "#fff" : C.muted }}>➤</span>}
              </button>
            </div>
            <div style={{ fontSize: 10, color: C.muted, marginTop: 5, textAlign: "center" }}>{t.ayurInputHint}</div>
          </div>
        </>
      )}
    </div>
  );
}

// ─── 2. DISEASE OUTBREAK ALERT ────────────────────────────────────────────────
const OUTBREAKS = [
  { disease: "Dengue", area: "Bangalore Urban, Karnataka", severity: "high", cases: 342, trend: "rising", icon: "🦟", prevention: ["Use mosquito nets", "Remove stagnant water", "Wear full sleeve clothes", "Use repellents"], symptoms: ["High fever", "Severe headache", "Joint pain", "Rash"] },
  { disease: "Cholera", area: "Raichur District, Karnataka", severity: "medium", cases: 87, trend: "stable", icon: "💧", prevention: ["Drink only boiled water", "Wash hands before eating", "Avoid raw street food", "Use ORS if diarrhea"], symptoms: ["Watery diarrhea", "Vomiting", "Dehydration", "Muscle cramps"] },
  { disease: "Malaria", area: "Mysuru District, Karnataka", severity: "low", cases: 23, trend: "falling", icon: "🦠", prevention: ["Sleep under bed nets", "Indoor spraying", "Anti-malarial tablets", "Remove water stagnation"], symptoms: ["Fever with chills", "Sweating", "Headache", "Vomiting"] },
  { disease: "Typhoid", area: "Tumkur, Karnataka", severity: "medium", cases: 156, trend: "rising", icon: "🌡️", prevention: ["Drink safe water", "Eat cooked food", "Wash hands thoroughly", "Get vaccinated"], symptoms: ["Prolonged fever", "Weakness", "Stomach pain", "Loss of appetite"] },
  { disease: "Chikungunya", area: "Hassan District, Karnataka", severity: "low", cases: 45, trend: "falling", icon: "🦟", prevention: ["Destroy mosquito breeding", "Use mosquito repellent", "Wear protective clothes", "Keep surroundings clean"], symptoms: ["Sudden fever", "Severe joint pain", "Rash", "Headache"] },
];

const SEVERITY_COLOR = { high: C.danger, medium: C.warn, low: "#4CAF50" };
const TREND_ICON = { rising: "📈", stable: "➡️", falling: "📉" };

function OutbreakScreen() {
  const { t } = useLang();
  const [selected, setSelected] = useState(null);
  const [district, setDistrict] = useState("Bangalore Urban");

  if (selected !== null) {
    const ob = OUTBREAKS[selected];
    const sColor = SEVERITY_COLOR[ob.severity];
    return (
      <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>
        <button onClick={() => setSelected(null)} style={{ background: "none", border: "none", color: C.textSub, fontSize: 13, cursor: "pointer", marginBottom: 14, display: "flex", alignItems: "center", gap: 5 }}>{t.backToAlerts}</button>
        <div style={{ animation: "fadeUp 0.4s ease" }}>
          <div style={{ padding: "16px", background: `${sColor}12`, border: `1.5px solid ${sColor}44`, borderRadius: 16, marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
              <span style={{ fontSize: 32 }}>{ob.icon}</span>
              <div>
                <div style={{ fontSize: 18, fontWeight: 800, color: C.text }}>{ob.disease}</div>
                <div style={{ fontSize: 11, color: C.muted }}>📍 {ob.area}</div>
              </div>
              <div style={{ marginLeft: "auto", textAlign: "right" }}>
                <div style={{ fontSize: 22, fontWeight: 800, color: sColor }}>{ob.cases}</div>
                <div style={{ fontSize: 10, color: C.muted }}>{t.cases}</div>
              </div>
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <span style={{ padding: "4px 10px", background: `${sColor}20`, border: `1px solid ${sColor}44`, borderRadius: 20, fontSize: 11, color: sColor, fontWeight: 700, textTransform: "uppercase" }}>{ob.severity} {t.risk}</span>
              <span style={{ padding: "4px 10px", background: C.card, border: `1px solid ${C.border}`, borderRadius: 20, fontSize: 11, color: C.textSub }}>{TREND_ICON[ob.trend]} {ob.trend}</span>
            </div>
          </div>

          <Card style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: C.warn, marginBottom: 10 }}>{t.watchSymptoms}</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>
              {ob.symptoms.map((s, i) => (
                <span key={i} style={{ padding: "5px 10px", background: `${C.warn}12`, border: `1px solid ${C.warn}33`, borderRadius: 20, fontSize: 11, color: C.warn }}>{s}</span>
              ))}
            </div>
          </Card>

          <Card>
            <div style={{ fontSize: 12, fontWeight: 700, color: "#4CAF50", marginBottom: 10 }}>{t.howToProtect}</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {ob.prevention.map((p, i) => (
                <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div style={{ width: 22, height: 22, borderRadius: 6, background: "#4CAF5020", border: "1px solid #4CAF5040", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, color: "#4CAF50", fontWeight: 800, flexShrink: 0 }}>{i + 1}</div>
                  <div style={{ fontSize: 13, color: C.text }}>{p}</div>
                </div>
              ))}
            </div>
          </Card>

          <div style={{ marginTop: 12, padding: "10px 14px", background: `${C.danger}10`, border: `1px solid ${C.danger}33`, borderRadius: 12, fontSize: 12, color: C.textSub, lineHeight: 1.5 }}>
            {t.emergencyCallPHC}
          </div>
        </div>
        <div style={{ height: 12 }} />
      </div>
    );
  }

  return (
    <div style={{ overflowY: "auto", padding: "16px 16px 8px", height: "100%" }}>
      {/* Header */}
      <div style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 16, fontWeight: 800, color: C.text, marginBottom: 2 }}>{t.outbreakTitle}</div>
        <div style={{ fontSize: 11, color: C.muted }}>{t.outbreakSubtitle}</div>
      </div>

      {/* District selector */}
      <Card style={{ marginBottom: 14, padding: "12px 14px" }}>
        <div style={{ fontSize: 11, color: C.accent, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 8 }}>{t.yourDistrict}</div>
        <div style={{ position: "relative" }}>
          <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", fontSize: 13, opacity: 0.5, pointerEvents: "none" }}>🏘️</span>
          <select value={district} onChange={e => setDistrict(e.target.value)}
            style={{ width: "100%", background: C.cardHover, border: `1.5px solid ${C.border}`, borderRadius: 10, padding: "10px 14px 10px 36px", fontSize: 13, color: C.text, appearance: "none", cursor: "pointer" }}>
            {["Bangalore Urban", "Bangalore Rural", "Mysuru", "Tumkur", "Hassan", "Raichur", "Bellary", "Bidar", "Dharwad", "Mandya"].map(d =>
              <option key={d} value={d} style={{ background: C.card }}>{d}</option>
            )}
          </select>
        </div>
      </Card>

      {/* Alert level summary */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 14 }}>
        {[{ label: t.highRisk, count: OUTBREAKS.filter(o => o.severity === "high").length, color: C.danger, icon: "🔴" },
        { label: t.mediumRisk, count: OUTBREAKS.filter(o => o.severity === "medium").length, color: C.warn, icon: "🟡" },
        { label: t.lowRisk, count: OUTBREAKS.filter(o => o.severity === "low").length, color: "#4CAF50", icon: "🟢" }].map((s, i) => (
          <Card key={i} style={{ textAlign: "center", padding: "10px 8px" }}>
            <div style={{ fontSize: 16, marginBottom: 2 }}>{s.icon}</div>
            <div style={{ fontSize: 18, fontWeight: 800, color: s.color }}>{s.count}</div>
            <div style={{ fontSize: 9, color: C.muted, lineHeight: 1.3 }}>{s.label}</div>
          </Card>
        ))}
      </div>

      {/* Outbreak list */}
      <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 10 }}>{t.activeAlertsNearYou}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {OUTBREAKS.map((ob, i) => {
          const sColor = SEVERITY_COLOR[ob.severity];
          return (
            <Card key={i} onClick={() => setSelected(i)} style={{ cursor: "pointer", animation: `fadeUp 0.4s ${i * 0.07}s ease both`, border: `1px solid ${sColor}33` }}
              onMouseEnter={e => e.currentTarget.style.borderColor = sColor + "88"}
              onMouseLeave={e => e.currentTarget.style.borderColor = sColor + "33"}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 44, height: 44, borderRadius: 12, background: `${sColor}15`, border: `1px solid ${sColor}33`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, flexShrink: 0 }}>{ob.icon}</div>
                <div style={{ flex: 1 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 3 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{ob.disease}</span>
                    <span style={{ fontSize: 10, padding: "2px 7px", background: `${sColor}20`, border: `1px solid ${sColor}44`, borderRadius: 10, color: sColor, fontWeight: 700 }}>{ob.severity}</span>
                  </div>
                  <div style={{ fontSize: 11, color: C.muted }}>📍 {ob.area}</div>
                </div>
                <div style={{ textAlign: "right", flexShrink: 0 }}>
                  <div style={{ fontSize: 16, fontWeight: 800, color: sColor }}>{ob.cases}</div>
                  <div style={{ fontSize: 9, color: C.muted }}>cases {TREND_ICON[ob.trend]}</div>
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      <div style={{ marginTop: 12, padding: "9px 12px", background: C.accentDim, border: `1px solid ${C.accentGlow}`, borderRadius: 10, fontSize: 10, color: C.muted, textAlign: "center" }}>
        {t.outbreakDataSrc}
      </div>
      <div style={{ height: 12 }} />
    </div>
  );
}

// ─── 3. VOICE-FIRST NAVIGATION ────────────────────────────────────────────────
function VoiceNavButton({ onNav }) {
  const { t, lang } = useLang();
  const [listening, setListening] = useState(false);
  const [status, setStatus] = useState("");
  const [show, setShow] = useState(false);

  const NAV_COMMANDS = {
    // English
    "home": ["home", "dashboard", "main", "start"],
    "symptom": ["symptom", "check", "symptoms", "disease", "sick", "ill"],
    "chat": ["chat", "talk", "medbot", "doctor", "ask"],
    "emergency": ["emergency", "help", "sos", "ambulance", "urgent"],
    "hospitals": ["hospital", "clinic", "nearby", "doctor", "find"],
    "reminder": ["medicine", "reminder", "tablet", "pill", "dose"],
    "library": ["library", "learn", "health", "info", "read"],
    "ayurveda": ["ayurveda", "herbs", "natural", "home remedy", "vaidya", "herbal"],
    "outbreak": ["outbreak", "alert", "disease", "epidemic", "warning", "danger"],
    "profile": ["profile", "account", "settings", "me", "my"],
  };

  const SCREEN_NAMES = {
    home: "Dashboard", symptom: "Symptom Checker", chat: "AI Chat",
    emergency: "Emergency", hospitals: "Nearby Hospitals", reminder: "Medicine Reminders",
    library: "Health Library", ayurveda: "Ayurveda AI", outbreak: "Disease Alerts", profile: "Profile"
  };

  const matchCommand = (transcript) => {
    const lower = transcript.toLowerCase();
    for (const [screen, keywords] of Object.entries(NAV_COMMANDS)) {
      if (keywords.some(k => lower.includes(k))) return screen;
    }
    return null;
  };

  const startVoiceNav = async () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { setStatus(t.voiceNotSupported); setShow(true); setTimeout(() => setShow(false), 2500); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());
    } catch {
      setStatus(t.micDeniedMsg); setShow(true); setTimeout(() => setShow(false), 2500); return;
    }
    const recog = new SR();
    recog.lang = STT_LANG[lang] || "en-IN";
    recog.interimResults = false;
    recog.onstart = () => { setListening(true); setStatus(t.listeningSayScreen); setShow(true); };
    recog.onend = () => { setListening(false); setTimeout(() => setShow(false), 2000); };
    recog.onresult = (e) => {
      const transcript = e.results[0][0].transcript;
      const match = matchCommand(transcript);
      if (match) {
        setStatus(`✅ ${t.goingTo} ${SCREEN_NAMES[match]}...`);
        speakText(`Opening ${SCREEN_NAMES[match]}`, STT_LANG[lang] || "en-IN");
        setTimeout(() => { onNav(match); setShow(false); }, 700);
      } else {
        setStatus(`❓ ${t.didntUnderstand} "${transcript}". ${t.voiceError.split(".")[1] || ""}`);
      }
    };
    recog.onerror = () => { setListening(false); setStatus(t.voiceError); };
    recog.start();
  };

  return (
    <div style={{ position: "relative" }}>
      {/* Floating voice nav popup */}
      {show && (
        <div style={{ position: "absolute", bottom: 52, right: 0, width: 220, padding: "12px 14px", background: C.card, border: `1.5px solid ${listening ? C.danger : C.accent}`, borderRadius: 14, boxShadow: `0 8px 30px #00000060`, animation: "fadeUp 0.3s ease", zIndex: 100 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: listening ? C.danger : C.accent, marginBottom: 6 }}>
            {listening ? t.voiceListening : t.voiceNav}
          </div>
          <div style={{ fontSize: 12, color: C.textSub, lineHeight: 1.5 }}>{status}</div>
          {listening && (
            <div style={{ display: "flex", gap: 3, alignItems: "flex-end", marginTop: 8, justifyContent: "center" }}>
              {[4, 8, 6, 10, 5, 9, 4, 7, 3].map((h, i) => (
                <div key={i} style={{ width: 3, height: h, background: C.danger, borderRadius: 2, animation: `typingDot 0.6s ${i * 0.08}s ease-in-out infinite` }} />
              ))}
            </div>
          )}
          {!listening && (
            <div style={{ marginTop: 8, fontSize: 10, color: C.muted }}>
              {t.sayNavItems}
            </div>
          )}
        </div>
      )}

      {/* Voice button */}
      <button onClick={startVoiceNav} title="Voice Navigation — say a screen name"
        style={{ width: 44, height: 44, borderRadius: 12, border: `1.5px solid ${listening ? C.danger : C.border}`, background: listening ? `linear-gradient(135deg,${C.danger},#C41E3A)` : C.card, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", transition: "all 0.25s", boxShadow: listening ? `0 0 0 4px ${C.danger}33` : C.accentGlow, position: "relative" }}>
        {listening && <div style={{ position: "absolute", inset: -5, borderRadius: 15, border: `2px solid ${C.danger}55`, animation: "ping 1s ease-out infinite", pointerEvents: "none" }} />}
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={listening ? "#fff" : C.textSub} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
          <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
          <line x1="12" y1="19" x2="12" y2="23" />
          <line x1="8" y1="23" x2="16" y2="23" />
        </svg>
      </button>
    </div>
  );
}

